function getNationalNumber(input) {
  if (typeof input !== "string") {
    return null;
  }

  const compact = input.replace(/[\s().-]/g, "");

  if (!/^\+?\d+$/.test(compact)) {
    return null;
  }

  let national;

  if (compact.startsWith("+")) {
    if (!compact.startsWith("+234")) {
      return null;
    }
    national = compact.slice(4);
  } else if (compact.startsWith("00234")) {
    national = compact.slice(5);
  } else if (compact.startsWith("234")) {
    national = compact.slice(3);
  } else if (compact.startsWith("0") && !compact.startsWith("00")) {
    national = compact.slice(1);
  } else {
    national = compact;
  }

  if (
    (compact.startsWith("+234") ||
      compact.startsWith("00234") ||
      compact.startsWith("234")) &&
    national.startsWith("0")
  ) {
    national = national.slice(1);
  }

  return /^[789][01]\d{8}$/.test(national) ? national : null;
}

export function normalizeNigerianPhone(input) {
  const national = getNationalNumber(input);
  return national === null ? null : `+234${national}`;
}

export function formatNigerianPhone(input) {
  const national = getNationalNumber(input);

  if (national === null) {
    return null;
  }

  return `0${national.slice(0, 3)} ${national.slice(3, 6)} ${national.slice(6)}`;
}
